#!/usr/bin/env node
'use strict';

const fs = require('fs');

function readElf(buf) {
  if (buf.length < 16 || buf[0] !== 0x7f || buf[1] !== 0x45 ||
      buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }

  const is64 = buf[4] === 2;
  const le = buf[5] === 1;
  const u16 = (off) => le ? buf.readUInt16LE(off) : buf.readUInt16BE(off);
  const u32 = (off) => le ? buf.readUInt32LE(off) : buf.readUInt32BE(off);
  const u64 = (off) => le ? Number(buf.readBigUInt64LE(off)) : Number(buf.readBigUInt64BE(off));

  const phoff = is64 ? u64(32) : u32(28);
  const shoff = is64 ? u64(40) : u32(32);
  const phentsize = is64 ? u16(54) : u16(42);
  const phnum = is64 ? u16(56) : u16(44);
  const shentsize = is64 ? u16(58) : u16(46);
  const shnum = is64 ? u16(60) : u16(48);
  const shstrndx = is64 ? u16(62) : u16(50);

  const loads = [];
  for (let i = 0; i < phnum; i++) {
    const off = phoff + i * phentsize;
    const type = u32(off);
    if (type !== 1) continue; // PT_LOAD
    let offset, vaddr, filesz, memsz, align;
    if (is64) {
      offset = u64(off + 8);
      vaddr = u64(off + 16);
      filesz = u64(off + 32);
      memsz = u64(off + 40);
      align = u64(off + 48);
    } else {
      offset = u32(off + 4);
      vaddr = u32(off + 8);
      filesz = u32(off + 16);
      memsz = u32(off + 20);
      align = u32(off + 28);
    }
    loads.push({ offset, vaddr, filesz, memsz, align });
  }

  return { is64, le, loads };
}

function pageSizeFor(loads) {
  let page = 0x1000;
  for (const s of loads) {
    if (s.align > page && (s.align & (s.align - 1)) === 0) page = s.align;
  }
  return page;
}

function buildImage(buf, loads, base, page, out) {
  if (loads.length === 0) return;

  let min = Infinity;
  let max = -Infinity;
  for (const s of loads) {
    min = Math.min(min, s.vaddr);
    max = Math.max(max, s.vaddr + Math.max(s.filesz, s.memsz));
  }
  min = Math.floor(min / page) * page;
  max = Math.ceil(max / page) * page;
  if (!isFinite(min) || !isFinite(max) || max <= min) return;

  const start = base + min;
  const size = max - min;
  const image = Buffer.alloc(size);

  for (const s of loads) {
    if (s.filesz === 0) continue;
    const dst = s.vaddr - min;
    const n = Math.min(s.filesz, size - dst, buf.length - s.offset);
    if (n > 0) buf.copy(image, dst, s.offset, s.offset + n);
  }

  for (let i = 0; i + 4 <= size; i += 4) {
    const addr = start + i;
    let value;
    if (out.le) {
      value = image.readUInt32LE(i);
    } else {
      value = image.readUInt32BE(i);
    }
    out.result[String(addr)] = value;
  }
}

function main() {
  const path = process.argv[2];
  if (!path) {
    console.error('usage: node extract.js <elf-binary>');
    process.exit(2);
  }

  const buf = fs.readFileSync(path);
  const elf = readElf(buf);
  const page = pageSizeFor(elf.loads);
  const out = { le: true, result: {} };

  // Common bases used when presenting an ELF's virtual memory.  For an
  // ET_DYN/PIE file these differ; for an ET_EXEC file the actual base is 0.
  const bases = [0, 0x400000];
  for (const base of bases) {
    buildImage(buf, elf.loads, base, page, out);
  }

  process.stdout.write(JSON.stringify(out.result));
  process.stdout.write('\n');
}

main();
